    schema: {"svg":"<svg viewBox=\"0 0 340 164\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\" fill=\"currentColor\" font-size=\"9\"><text x=\"170\" y=\"14\" font-size=\"9\" text-anchor=\"middle\">Deux AOC sans bulles sur l’aire du champagne</text><rect x=\"10\" y=\"24\" width=\"155\" height=\"128\" rx=\"3\" fill-opacity=\"0.1\" stroke=\"currentColor\"/><text x=\"18\" y=\"40\" font-size=\"9.5\"><tspan font-weight=\"bold\">Coteaux champenois</tspan></text><text x=\"18\" y=\"56\" font-size=\"8.5\">reconnus en 1974</text><text x=\"18\" y=\"69\" font-size=\"8.5\">blancs, rosés et rouges</text><text x=\"18\" y=\"82\" font-size=\"8.5\">cépages de la Champagne</text><text x=\"18\" y=\"95\" font-size=\"8.5\">élevés au moins jusqu’au</text><text x=\"18\" y=\"108\" font-size=\"8.5\"><tspan font-weight=\"bold\">15 août</tspan> suivant la récolte</text><text x=\"18\" y=\"121\" font-size=\"8.5\">nom de la commune possible</text><text x=\"18\" y=\"134\" font-size=\"8.5\">en complément</text><rect x=\"175\" y=\"24\" width=\"155\" height=\"128\" rx=\"3\" fill-opacity=\"0.3\" stroke=\"currentColor\"/><text x=\"183\" y=\"40\" font-size=\"9.5\"><tspan font-weight=\"bold\">Rosé des Riceys</tspan></text><text x=\"183\" y=\"56\" font-size=\"8.5\">appellation de 1947</text><text x=\"183\" y=\"69\" font-size=\"8.5\">rosé tranquille de <tspan font-weight=\"bold\">pinot noir seul</tspan></text><text x=\"183\" y=\"82\" font-size=\"8.5\"></text><text x=\"183\" y=\"95\" font-size=\"8.5\">vendange entière,</text><text x=\"183\" y=\"108\" font-size=\"8.5\">macération semi-carbonique</text><text x=\"183\" y=\"121\" font-size=\"8.5\">une seule commune :</text><text x=\"183\" y=\"134\" font-size=\"8.5\">Riceys (Aube)</text></svg>\n","legende":"Les deux vins tranquilles champenois : Coteaux champenois et Rosé des Riceys","src":"Schéma original d’après les cahiers des charges AOC Coteaux champenois (BO-agri, 7 août 2025) et Rosé des Riceys (BO-agri, 13 avril 2023), INAO"},
